package br.com.admeclesial.application.usuario;
import org.springframework.beans.factory.annotation.Autowired; import org.springframework.security.access.AccessDeniedException; import br.com.admeclesial.domain.usuario.*; import br.com.admeclesial.infrastructure.persistence.usuario.*; import br.com.admeclesial.infrastructure.persistence.pessoa.PessoaRepository; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.util.stream.Collectors;
@Service public class UsuarioApplicationService { @Autowired private SegurancaOrganizacaoService seguranca; private final UsuarioRepository usuarios; private final UsuarioPerfilRepository perfis; private final UsuarioOrganizacaoRepository acessos; private final PessoaRepository pessoas; private final OrganizacaoEclesialRepository organizacoes; private final PasswordEncoder encoder;
 public UsuarioApplicationService(UsuarioRepository u,UsuarioPerfilRepository p,UsuarioOrganizacaoRepository a,PessoaRepository pe,OrganizacaoEclesialRepository o,PasswordEncoder e){usuarios=u;perfis=p;acessos=a;pessoas=pe;organizacoes=o;encoder=e;}
 @Transactional public UsuarioResponse criar(UsuarioRequest r){validarOrganizacoes(r.organizacoes());validarPessoa(r.pessoaUuid());if(r.senha()==null||r.senha().isBlank())throw new IllegalArgumentException("Senha é obrigatória na criação"); if(usuarios.existsByLoginIgnoreCase(r.login()))throw new IllegalArgumentException("Login já cadastrado"); var pessoa=pessoas.findByUuid(r.pessoaUuid()).orElseThrow(()->new IllegalArgumentException("Pessoa não encontrada")); if(!pessoa.isAtivo())throw new IllegalArgumentException("Pessoa inativa"); var u=new Usuario();u.setPessoa(pessoa);u.setLogin(r.login().trim());u.setSenhaHash(encoder.encode(r.senha()));u.setAtivo(r.ativo());u=usuarios.save(u); salvarAcessos(u,r.perfis(),r.organizacoes()); return toResponse(u);}
 @Transactional public UsuarioResponse atualizar(UUID uuid,UsuarioRequest r){var u=buscar(uuid);validarUsuarioGerenciavel(u);validarOrganizacoes(r.organizacoes());validarPessoa(r.pessoaUuid()); var atual=SecurityContextHolder.getContext().getAuthentication(); boolean proprio=atual!=null&&u.getLogin().equalsIgnoreCase(atual.getName()); if(proprio&&!r.ativo())throw new IllegalArgumentException("Administrador não pode desativar o próprio usuário"); if(proprio&&!r.perfis().contains(PerfilAcesso.ADMINISTRADOR)&&perfis.existsByUsuarioIdAndPerfil(u.getId(),PerfilAcesso.ADMINISTRADOR))throw new IllegalArgumentException("Administrador não pode remover o próprio perfil ADMINISTRADOR"); u.setLogin(r.login().trim());u.setAtivo(r.ativo());if(r.senha()!=null&&!r.senha().isBlank())u.setSenhaHash(encoder.encode(r.senha())); usuarios.save(u);perfis.deleteByUsuarioId(u.getId());acessos.deleteByUsuarioId(u.getId());salvarAcessos(u,r.perfis(),r.organizacoes());return toResponse(u);}
 @Transactional(readOnly=true) public List<UsuarioResponse> listar(){var os=seguranca.organizacoesAutorizadas();return usuarios.findAllByOrderByLoginAsc().stream().filter(u->acessos.findByUsuarioId(u.getId()).stream().allMatch(a->os.contains(a.getOrganizacao().getUuid()))).map(this::toResponse).toList();}
 @Transactional(readOnly=true) public UsuarioResponse obter(UUID uuid){var u=buscar(uuid);validarUsuarioGerenciavel(u);return toResponse(u);}
 private void validarOrganizacoes(Set<UUID> os){for(var id:os)seguranca.validarAcesso(id);} private void validarPessoa(UUID uuid){var os=seguranca.organizacoesAutorizadas();if(os.isEmpty()||!pessoas.isVisivel(uuid,os))throw new AccessDeniedException("Pessoa fora das organizações autorizadas");} private void validarUsuarioGerenciavel(Usuario u){var permitidas=seguranca.organizacoesAutorizadas();var alvo=acessos.findByUsuarioId(u.getId());if(alvo.stream().anyMatch(a->!permitidas.contains(a.getOrganizacao().getUuid())))throw new AccessDeniedException("Usuário possui acesso fora das organizações administráveis");} private Usuario buscar(UUID uuid){return usuarios.findByUuid(uuid).orElseThrow(()->new IllegalArgumentException("Usuário não encontrado"));}
 private void salvarAcessos(Usuario u,Set<PerfilAcesso> ps,Set<UUID> os){for(var p:ps){var up=new UsuarioPerfil();up.setUsuario(u);up.setPerfil(p);perfis.save(up);} for(var id:os){var o=organizacoes.findByUuid(id).orElseThrow(()->new IllegalArgumentException("Organização não encontrada"));if(!o.isAtivo())throw new IllegalArgumentException("Organização inativa");var a=new UsuarioOrganizacao();a.setUsuario(u);a.setOrganizacao(o);acessos.save(a);}}
 private UsuarioResponse toResponse(Usuario u){var ps=perfis.findByUsuarioId(u.getId()).stream().map(UsuarioPerfil::getPerfil).collect(Collectors.toCollection(LinkedHashSet::new));var os=acessos.findByUsuarioId(u.getId()).stream().map(x->x.getOrganizacao().getUuid()).collect(Collectors.toCollection(LinkedHashSet::new));return new UsuarioResponse(u.getUuid(),u.getPessoa().getUuid(),u.getPessoa().getNome(),u.getLogin(),u.isAtivo(),ps,os);}
}
